/bin/bash -lc "python - <<'PY'
import json, os, pathlib, sys, urllib.request
history_id = 'bbd44e69cb8906b5b3211c1182175731'
key_path = os.environ.get('GALAXY_API_KEY_FILE')
if not key_path:
    raise SystemExit('GALAXY_API_KEY_FILE is not set')
api_key = pathlib.Path(key_path).read_text().strip()
base = 'https://usegalaxy.org'
urls = [
    ('ucsc_hg38_chr19_44907187_sequence.json', 'https://api.genome.ucsc.edu/getData/sequence?genome=hg38;chrom=chr19;start=44907186;end=44907187'),
    ('ucsc_hg38_encode4_cCREregistry_chr19_44907186_44907187.json', 'https://api.genome.ucsc.edu/getData/track?genome=hg38;track=cCREregistry;chrom=chr19;start=44907186;end=44907187'),
]
payload = {
    'history_id': history_id,
    'targets': [{
        'destination': {'type': 'hdas'},
        'items': [
            {'src': 'url', 'url': url, 'ext': 'json', 'dbkey': 'hg38', 'name': name}
            for name, url in urls
        ]
    }]
}
req = urllib.request.Request(
    base + '/api/tools/fetch',
    data=json.dumps(payload).encode('utf-8'),
    headers={'Content-Type': 'application/json', 'x-api-key': api_key},
    method='POST',
)
with urllib.request.urlopen(req, timeout=60) as resp:
    out = json.loads(resp.read().decode('utf-8'))
print(json.dumps({
    'jobs': [{'id': j.get('id'), 'state': j.get('state'), 'tool_id': j.get('tool_id')} for j in out.get('jobs', [])],
    'outputs': [{'id': d.get('id'), 'name': d.get('name'), 'state': d.get('state')} for d in out.get('outputs', [])]
}, indent=2))
PY"
